/**
 * Ambient module declaration for raw `.sql` imports. `migrations.js`
 * (generated by `drizzle-kit generate`, see `drizzle.config.ts`) imports each
 * migration's `.sql` file directly; `babel-plugin-inline-import` (wired in
 * `babel.config.js`) inlines its contents as a string at bundle time.
 */
declare module '*.sql' {
  const sql: string;
  export default sql;
}
